fn build_bdd_acceptance_criteria(part: &PartDef) -> String {
    let mut acs = Vec::new();
    let name = sanitize_id(&part.name);

    // Pattern A: Nominal Domain State & Signal Model
    acs.push(format!(
        "- [ ] AC-01: Given nominal {} state vector, When command signals are received, Then updates domain attributes within declared bounds.",
        name
    ));

    // Pattern B: Constraint & Safety Invariant Satisfaction
    if !part.constraints.is_empty() {
        for (idx, c) in part.constraints.iter().enumerate() {
            acs.push(format!(
                "- [ ] AC-{:02}: Given invariant condition, When {} evaluates constraint '{}', Then asserts satisfaction without violation.",
                idx + 2, name, c.name
            ));
        }
    } else {
        acs.push(format!(
            "- [ ] AC-02: Given formal constraints, When {} evaluates state invariants, Then asserts operational safety parameters.",
            name
        ));
    }

    // Pattern C: Negative Failsafe & Error Recovery
    let next_id = acs.len() + 1;
    acs.push(format!(
        "- [ ] AC-{:02}: Given malformed input signals or boundary violation, When {} error recovery activates, Then transitions to safe fallback state.",
        next_id, name
    ));

    acs.join("\n")
}
