/// Locate and read authoritative SysML v2 model content (schema/*.sysml or .pipeline/schema.sysml).
pub fn discover_sysml_model_text(repo_root: &Path) -> Result<Option<String>, String> {
    let schema_dir = repo_root.join("schema");
    if schema_dir.is_dir() {
        let mut sysml_contents = Vec::new();
        let entries = fs::read_dir(&schema_dir)
            .map_err(|e| format!("Unable to read schema directory {}: {}", schema_dir.display(), e))?;

        let mut paths: Vec<_> = entries
            .filter_map(|e| e.ok())
            .map(|e| e.path())
            .filter(|p| {
                let name = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
                p.is_file() && !name.starts_with('.') && p.extension().map(|ext| ext == "sysml").unwrap_or(false)
            })
            .collect();
        paths.sort();

        for p in paths {
            let content = fs::read_to_string(&p)
                .map_err(|e| format!("Failed to read SysML schema file {}: {}", p.display(), e))?;
            if !content.trim().is_empty() {
                sysml_contents.push(content);
            }
        }

        if !sysml_contents.is_empty() {
            return Ok(Some(sysml_contents.join("\n\n")));
        }
    }

    let pipeline_model = repo_root.join(".pipeline").join("schema.sysml");
    if pipeline_model.is_file() {
        let content = fs::read_to_string(&pipeline_model)
            .map_err(|e| format!("Failed to read pipeline schema {}: {}", pipeline_model.display(), e))?;
        if !content.trim().is_empty() {
            return Ok(Some(content));
        }
    }

    Ok(None)
}
```

