// 1. Replace find_sysml_in_dir with recursive discover_sysml_files:
use walkdir::WalkDir;

pub fn discover_sysml_files(dir: &Path) -> Result<Vec<PathBuf>, String> {
    if !dir.is_dir() {
        return Err(format!("Directory does not exist: {}", dir.display()));
    }
    let mut files = Vec::new();
    for entry in WalkDir::new(dir).follow_links(true).into_iter().filter_map(|e| e.ok()) {
        let p = entry.path();
        if p.is_file() && p.extension().map_or(false, |ext| ext == "sysml") {
            files.push(p.to_path_buf());
        }
    }
    files.sort();
    if files.is_empty() {
        return Err(SCHEMA_REMEDIATION_MESSAGE.to_string());
    }
    Ok(files)
}

// 2. In crates/compile-sysml/src/lib.rs / main.rs:
// Provide parse_sysml_tree to recursively parse and merge all discovered files:
pub fn parse_sysml_tree(root_dir: &Path) -> Result<PackageDef, String> {
    let files = discover_sysml_files(root_dir)?;
    let mut root_pkg = PackageDef {
        name: "SysML_Root".to_string(),
        ..Default::default()
    };
    for file in files {
        let text = fs::read_to_string(&file)
            .map_err(|e| format!("Failed to read {}: {}", file.display(), e))?;
        let pkg = parse_sysml(&text)
            .map_err(|e| format!("Parse error in {}: {}", file.display(), e))?;
        merge_package_defs(&mut root_pkg, pkg);
    }
    Ok(root_pkg)
}
